// This is not autogenerated.
package academy

import (
	"encoding/json"
	"fmt"
	"strconv"
	"strings"
)

// QuizTimeLimit is a quiz time limit in minutes.
//
// It exists because both JSON shapes below are real production data and no
// plain scalar can decode both:
//
//   - a JSON number, which is what academy-theme emits today
//     (`int (or $p.timeLimit $p.time_limit 0)` in partials/test/single.html);
//   - a JSON string, which is what payloads persisted by earlier revisions
//     hold - "25", "0", "30", and the non-numeric sentinel "infinite".
//
// Typing the field as an integer breaks the stored rows; typing it as a string
// breaks every freshly built quiz. The schema therefore models it as
// `oneOf: [integer, string]` and this type absorbs both.
//
// A string that does not parse to a positive number means "no time limit" and
// normalizes to 0, matching the documented meaning of 0 and the behaviour the
// UI already relies on (`parseInt`, then `NaN` or <= 0 means no limit). It is
// deliberately lenient rather than strict: this whole construct was brought
// down by one unreadable record aborting an entire response, so an
// unrecognized time limit degrades to "untimed" instead of failing the decode.
type QuizTimeLimit int

// Minutes returns the time limit in minutes; 0 means no time limit.
func (t QuizTimeLimit) Minutes() int { return int(t) }

// IsUnlimited reports whether the quiz is untimed.
func (t QuizTimeLimit) IsUnlimited() bool { return t <= 0 }

// UnmarshalJSON decodes a time limit from either a JSON number or a JSON
// string. Unparseable and negative values decode to 0 (no time limit).
func (t *QuizTimeLimit) UnmarshalJSON(data []byte) error {
	if len(data) == 0 || string(data) == "null" {
		*t = 0
		return nil
	}

	var number int
	if err := json.Unmarshal(data, &number); err == nil {
		if number < 0 {
			number = 0
		}
		*t = QuizTimeLimit(number)
		return nil
	}

	var text string
	if err := json.Unmarshal(data, &text); err != nil {
		return fmt.Errorf("decode quiz time limit from %s: %w", string(data), err)
	}

	// "infinite", "" and any other non-numeric value all mean "no time limit".
	parsed, err := strconv.Atoi(strings.TrimSpace(text))
	if err != nil || parsed < 0 {
		*t = 0
		return nil
	}

	*t = QuizTimeLimit(parsed)
	return nil
}

// MarshalJSON always emits a number, normalizing the legacy string form so
// that everything written from here on is canonical.
func (t QuizTimeLimit) MarshalJSON() ([]byte, error) {
	if t < 0 {
		return json.Marshal(0)
	}
	return json.Marshal(int(t))
}
